Record Product
  Define name As String;
  Define price, stock As Integer;
EndRecord

Function amount <- Amount(price As Integer, quantity As Integer)
  Define amount As Integer;
  amount <- price * quantity;
EndFunction

Function discounted <- WithDiscount(total As Integer)
  Define discounted As Integer;
  discounted <- total - total Div 10;
EndFunction

Function valid <- ValidCode(codigo As Integer)
  Define valid As Boolean;
  valid <- codigo >= 1 And codigo <= 5;
EndFunction

Function text <- InventoryJson(products As Vector<Product>)
  Define text As String <- "{";
  For Each product In products Do
    If text <> "{" Then
      text <- text + ", ";
    EndIf
    text <- text + '"' + product.name + '": ' + toText(product.stock);
  EndFor
  text <- text + "}";
EndFunction

Subroutine Catalog() As Vector<Product>
  Define products As Vector<Product> <- vector();
  products.append(Product("Juice", 3, 10));
  products.append(Product("Sandwich", 5, 5));
  products.append(Product("Biscuit", 2, 8));
  products.append(Product("Water", 1, 12));
  products.append(Product("Fruit", 2, 6));
  Return products;
EndSubroutine

Algorithm Kiosk
  Define products As Vector<Product> <- Catalog();
  Define total As Integer <- 0;
  Define codigo, quantity As Integer;
  Read codigo;
  While codigo <> 0 Do
    Read quantity;
    If Not ValidCode(codigo) Then
      Write "Code ", codigo, " does not exist";
    Else
      If quantity < 1 Then
        Write "Quantity ", quantity, " is not valid";
      Else
        Define product As Product <- products[codigo - 1];
        If quantity > product.stock Then
          Write product.name, " x ", quantity, " rejected: remaining ", product.stock;
        Else
          product.stock <- product.stock - quantity;
          products[codigo - 1] <- product;
          Write product.name, " x ", quantity, " = ", Amount(product.price, quantity);
          total <- total + Amount(product.price, quantity);
        EndIf
      EndIf
    EndIf
    Read codigo;
  EndWhile
  Write "Total: ", total;
  Write "With discount: ", WithDiscount(total);
  Write "Inventory: ", InventoryJson(products);
EndAlgorithm
